// fin.year_fraction's members: one function per member, each declared by the //kavun:member directive in its doc
// comment. The table, yearFractionMethods, and the member entries of docs/reference/types/fin_year_fraction.md
// (alphabetical, so the order here is free) are generated by cmd/kavun-gen — run `go generate ./...` after changing a
// directive or a doc comment.

// Report truthiness: `0/1` is falsy, every other fraction truthy.
//
//kavun:member is_true pure () -> bool
func yearFractionIsTrue(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	t, err := core.ValueTypes[v.Type].IsTrue(v)
	if err != nil {
		return core.Undefined, err
	}
	return core.BoolValue(t), nil
}

// Render the year fraction per the [format mini-language](../../format_mini_language.md).
//
//kavun:member format pure ([spec]) -> string
func yearFractionFormat(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	return core.FormatWithSpec(v, id, args)
}

// Answer the year fraction itself — it is immutable.
//
//kavun:member copy pure () -> fin.year_fraction
func yearFractionCopy(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

// Answer the year fraction itself; see [`copy`](#copy).
//
//kavun:member freeze pure () -> fin.year_fraction
func yearFractionFreeze(_ core.VM, v core.Value, _ member.ID, _ []core.Value) (core.Value, error) {
	return v, nil
}

// Answer `[n1, d1]` or `[n1, d1, n2, d2]`; `fin.year_fraction(f.terms()...) == f` always holds.
//
//kavun:member terms pure () -> array
func yearFractionTerms(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	f := YearFractionOf(v)
	t := yearFractionTermsOf(f)
	out := make([]core.Value, len(t))
	for i, n := range t {
		out[i] = core.IntValue(n)
	}
	return core.NewArrayValue(out, false), nil
}

// Answer the decimal reading at a stated rounding — the only bridge to `decimal`.
//
//kavun:member value pure (scale, mode) -> decimal
func yearFractionValue(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	name := id.String()
	f := YearFractionOf(v)
	// the decimal reading, at a stated rounding — the only bridge to decimal
	scale, mode, err := core.ScaleModeArgs(name, args, 0)
	if err != nil {
		return core.Undefined, err
	}
	d, err := f.Value(scale, mode)
	if err != nil {
		return core.Undefined, errs.NewInvalidValueError(fmt.Sprintf("(%s) %s", name, err))
	}
	return core.DecimalResult(name, d)
}

// Answer the terms as text: `"31/365"`, `"184/365+182/366"` — also what `f"{f}"` renders.
//
//kavun:member string pure ([default]) -> string
func yearFractionString(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	f := YearFractionOf(v)
	return core.ConvMember(id.String(), yearFractionTypeName, args, true, core.NewStringValue(f.String()))
}

// Report whether the fraction is zero.
//
//kavun:member is_zero pure () -> bool
func yearFractionIsZero(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	f := YearFractionOf(v)
	n, _ := f.Rational()
	return core.BoolValue(n == 0), nil
}

// Report whether the fraction is negative — a period running backwards; see [`is_zero`](#is_zero).
//
//kavun:member is_negative pure () -> bool
func yearFractionIsNegative(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	f := YearFractionOf(v)
	n, _ := f.Rational()
	return core.BoolValue(n < 0), nil
}

// Report whether the fraction is positive; see [`is_zero`](#is_zero).
//
//kavun:member is_positive pure () -> bool
func yearFractionIsPositive(_ core.VM, v core.Value, id member.ID, args []core.Value) (core.Value, error) {
	f := YearFractionOf(v)
	n, _ := f.Rational()
	return core.BoolValue(n > 0), nil
}
